:root {
  --ink: #20252b;
  --paper: #fffdf7;
  --line: #d9d5ca;
  --amber: #f2b544;
  --amber-deep: #9b6200;
  --mist: #f1eee5;
  --success: #28745d;
}

.mission-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.mission-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--amber);
  border-bottom: 2px solid var(--ink);
}

.mission-mark {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  color: var(--paper);
  background: var(--ink);
  border-radius: 9px;
  font-size: 20px;
  font-weight: 700;
}

.mission-title {
  flex: 1;
  margin: 0;
  font-size: 13px;
  line-height: 1.25;
}

.mission-title strong {
  display: block;
  font-size: 17px;
}

.mission-code {
  padding: 5px 7px;
  color: var(--amber-deep);
  background: var(--paper);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
}

.mission-body {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 16px;
  padding: 15px 16px;
}

.mission-info {
  display: grid;
  gap: 7px;
}

.info-row {
  display: flex;
  justify-content: space-between;
  margin: 0;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}

.info-row span {
  color: var(--amber-deep);
  font-weight: 800;
}

.task-list {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
}

.task-list li {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 8px;
  background: var(--mist);
  border-radius: 7px;
}

.check {
  color: var(--success);
  font-weight: 900;
}

.mission-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  background: var(--mist);
  border-top: 1px solid var(--line);
}

.status {
  color: var(--success);
  font-size: 12px;
  font-weight: 800;
}

.mission-foot button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 7px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
}
